#pragma once

#include "scop40bench.h"
#include "fastbench.h"
#include "flat_profiles.h"
#include "flat_aligner.h"
#include "flat_alphas.h"
#include "paralign.h"

class flat_bench : public FastBench
	{
public:
// Hard-coded score-like not Evalue-like
//	SBSCORE m_SBS = SBS_Evalue;

////////////////////////////////
// Hits generated by this search
////////////////////////////////
	atomic<uint> m_NextQueryIdx = 0;
	atomic<uint> m_NextDopeIdx = 0;

//////////////////////////////
// Flat profiles
// May be superset of lookup
//////////////////////////////
	flat_profiles m_fp;
	float *m_self_rev_scores = 0;
	float *m_nu_self_rev_scores = 0;

//////////////////////////////
// Distance matrices for
// structure features:
//	lddt, entropy, dali
//////////////////////////////
	vector<sid_t *> m_distmxs;

//////////////////////////////
// Nu support
//////////////////////////////
	static bool m_nu_filter;
	static bool m_nu_only;

public:
	static atomic<uint> m_aligned_pair_count;
	static atomic<uint> m_ncachehits;
	static atomic<uint> m_ncachemisses;
	static atomic<bool> m_max_secs_exceeded;

public:
	void Search(uint ThreadCount, bool PinThreads, bool UseDope, uint MaxSecs);
	void Launch(uint ThreadCount, bool PinThreads, bool UseDope, uint MaxSecs);
	void ApplyWeightsToLogOdds(const unordered_map<string, float> &Weights);
	void SetScalarParams(
		const vector<string> &Names,
		const vector<float> &Values);
	void UpdateParamsFromVarStr(const string &VarStr);
	void UpdateParamsFromVarStr(
		const vector<string> &names, const vector<float> &values);
	void load_profiles_fapattern(const string &fafnpattern);
	void load_profiles_chains(const vector<flat_chain_t *> &chains);
	void LogParams(bool show_progress = false) const;
	void align_pair(flat_aligner &fa,
		const string &labelQ, const string &labelT);
	void align_pair_selfrev(FILE *f, uint DomIdx);
	void set_selfrev_scores();
	void set_nu_selfrev_scores();
	void set_distmxs(const vector<flat_chain_t *> &chains);

	void doQ(flat_aligner &fa, uint domidxQ, uint domidxT);
	void doT(flat_aligner &fa, uint domidxT);

	void init_nu_filter(const string &hexfafn = "");

	const uint8_t *get_nu_codeseq(uint domidx) const
		{
		return (m_nu_filter ? m_fp.m_nu_codeseqs[domidx] : 0);
		}

	const uint8_t *get_nu_codeseq_rev(uint domidx) const
		{
		return (m_nu_filter ? m_fp.m_nu_codeseqs_rev[domidx] : 0);
		}

public:
	virtual void ThreadBody_All(uint ThreadIdx);
	virtual void ThreadBody_Dope(uint ThreadIdx);

public:
	static void ClassifyParams(
		const vector<string> &Names,
		const vector<float> &Values,
		vector<string> &AlphaNames,
		vector<float> &Weights,
		vector<string> &ScalarNames,
		vector<float> &ScalarValues);

	static void StaticThreadBody(flat_bench *SB,
		uint ThreadIdx, bool UseDope);

	static void StaticThreadBody_MaxSecs(uint MaxSecs);
	};

void TruncLabel(string &Label);
